<?php
if(!$isDeveloper){echo '<div class="panel"><h3>Akses ditolak</h3><p>Halaman ini hanya untuk developer.</p></div>';return;}
$customers=$conn->query("SELECT u.id,u.nama,u.email,u.role,u.plan_code,u.plan_status,u.plan_expires_at,u.created_at,COALESCE(s.nama_usaha,'-') nama_usaha FROM users u LEFT JOIN settings s ON s.user_id=u.id WHERE u.role<>'developer' ORDER BY u.id DESC");
$licenses=$conn->query("SELECT l.*,u.email FROM licenses l LEFT JOIN users u ON u.id=l.used_by ORDER BY l.id DESC LIMIT 30");
$total=(int)$conn->query("SELECT COUNT(*) c FROM users WHERE role<>'developer'")->fetch_assoc()['c'];
$active=(int)$conn->query("SELECT COUNT(*) c FROM users WHERE role<>'developer' AND plan_status='active'")->fetch_assoc()['c'];
$expired=0;
echo '<div class="saas-head"><div><span class="section-kicker">DEVELOPER CONTROL CENTER</span><h1>Kelola TokoFlow SaaS</h1><p class="muted">Kelola pelanggan dan lisensi dari satu tempat. Jangan membagikan source code ke pelanggan.</p></div><span class="tag">Developer only</span></div>';
if(isset($_GET['created']))echo '<div class="alert good">Lisensi dibuat: <b>'.e($_GET['created']).'</b> — simpan kode ini untuk pelanggan.</div>';
if(isset($_GET['customer_created']) && !empty($_SESSION['new_customer'])){
  $nc=$_SESSION['new_customer'];
  $access="TOKOFLOW\n\nLink: (isi setelah domain/hosting aktif)\nToko: {$nc['shop']}\nPemilik: {$nc['nama']}\nEmail: {$nc['email']}\nPassword sementara: {$nc['password']}\nLicense Key: {$nc['license']}\nPaket: ".strtoupper($nc['plan'])."\nMasa berlaku: UNLIMITED";
  echo '<div class="customer-created panel"><div><span class="section-kicker">AKUN PELANGGAN BERHASIL DIBUAT</span><h3>'.e($nc['shop']).'</h3><p class="muted">Akun, toko, paket, dan lisensi sudah saling terhubung. Password sementara hanya ditampilkan sekarang.</p></div><div class="access-grid"><div><small>Email</small><code>'.e($nc['email']).'</code></div><div><small>Password sementara</small><code>'.e($nc['password']).'</code></div><div><small>License Key</small><code>'.e($nc['license']).'</code></div><div><small>Paket / Masa berlaku</small><code>'.e(strtoupper($nc['plan']).' / UNLIMITED').'</code></div></div><button type="button" class="primary copy-access" data-access="'.e($access).'">📋 Salin Data Akses</button></div>';
  unset($_SESSION['new_customer']);
}
if(isset($_GET['updated']))echo '<div class="alert good">Data pelanggan berhasil diperbarui.</div>';
echo '<div class="cards saas-stats"><div><small>Total pelanggan</small><b>'.$total.'</b></div><div><small>Lisensi aktif</small><b>'.$active.'</b></div><div><small>Perlu perhatian</small><b>'.$expired.'</b></div></div>';
echo '<div class="twopan"><section class="panel"><h3>＋ Buat Akun Pelanggan</h3><p class="muted">Buat akun pemilik toko sekaligus toko, paket, password sementara, dan license key.</p><form method="post"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="act" value="developer_create_customer"><label>Nama pemilik</label><input name="nama" placeholder="Contoh: Ahmad" required><label>Nama toko</label><input name="shop" placeholder="Contoh: Toko Makmur" required><label>Email login</label><input type="email" name="email" placeholder="pemilik@email.com" required><label>Paket</label><select name="plan"><option value="basic">Basic</option><option value="pro" selected>Pro</option><option value="business">Business</option></select><p class="muted">Masa berlaku: <b>UNLIMITED</b></p><button class="primary full">＋ Buat Akun + Lisensi</button></form></section><section class="panel"><h3>Buat License Key Manual</h3><form method="post"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="act" value="developer_create_license"><label>Paket</label><select name="plan"><option value="basic">Basic</option><option value="pro" selected>Pro</option><option value="business">Business</option></select><p class="muted">Masa berlaku: <b>UNLIMITED</b></p><button class="primary full">＋ Buat Lisensi</button></form></section><section class="panel"><h3>Aturan SaaS</h3><div class="row"><span>Source code</span><b>Tetap di server</b></div><div class="row"><span>Data pelanggan</span><b>Terpisah per akun</b></div><div class="row"><span>Validasi</span><b>Akun + lisensi</b></div><p class="muted">Versi ini adalah fondasi lokal untuk diuji di XAMPP. Sebelum produksi, tambahkan HTTPS, backup otomatis, rate limit, dan pembayaran gateway.</p></section></div>';
echo '<section class="panel"><div class="panelhead"><h3>Pelanggan</h3><span class="muted">'.$total.' akun</span></div><div class="tablewrap"><table><thead><tr><th>Toko / Pemilik</th><th>Paket</th><th>Status</th><th>Masa berlaku</th><th>Ubah</th></tr></thead><tbody>';
while($c=$customers->fetch_assoc()){
  echo '<tr><td><b>'.e($c['nama_usaha']).'</b><small>'.e($c['nama']).' · '.e($c['email']).'</small></td><td>'.e(strtoupper($c['plan_code']??'basic')).'</td><td>'.e($c['plan_status']??'active').'</td><td><b>UNLIMITED</b></td><td><details><summary>Edit</summary><form method="post"><input type="hidden" name="csrf" value="'.e(csrf()).'"><input type="hidden" name="act" value="developer_update_customer"><input type="hidden" name="customer_id" value="'.(int)$c['id'].'"><label>Paket</label><select name="plan"><option '.(($c['plan_code']??'basic')==='basic'?'selected':'').' value="basic">Basic</option><option '.(($c['plan_code']??'basic')==='pro'?'selected':'').' value="pro">Pro</option><option '.(($c['plan_code']??'basic')==='business'?'selected':'').' value="business">Business</option></select><label>Status</label><select name="status"><option '.(($c['plan_status']??'active')==='active'?'selected':'').' value="active">Aktif</option><option '.(($c['plan_status']??'active')==='suspended'?'selected':'').' value="suspended">Ditangguhkan</option></select><p class="muted">Masa berlaku: <b>UNLIMITED</b></p><button class="primary">Simpan</button></form></details></td></tr>';
}
echo '</tbody></table></div></section>';
echo '<section class="panel"><div class="panelhead"><h3>License Keys</h3><span class="muted">30 terakhir</span></div><div class="tablewrap"><table><thead><tr><th>Kode</th><th>Paket</th><th>Masa berlaku</th><th>Status</th><th>Dipakai oleh</th></tr></thead><tbody>';
while($l=$licenses->fetch_assoc())echo '<tr><td><code>'.e($l['code']).'</code></td><td>'.e(strtoupper($l['plan_code'])).'</td><td><b>UNLIMITED</b></td><td>'.($l['used_by']?'Terpakai':'Tersedia').'</td><td>'.e($l['email']??'-').'</td></tr>';
echo '</tbody></table></div></section>';
echo '<script>document.querySelectorAll(".copy-access").forEach(function(btn){btn.addEventListener("click",async function(){try{await navigator.clipboard.writeText(this.dataset.access);this.textContent="✓ Data akses tersalin";setTimeout(()=>this.textContent="📋 Salin Data Akses",1800)}catch(e){alert(this.dataset.access)}})});</script>';
?>
